"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68468"],{52594(e){e.exports=JSON.parse('{"id":"F071","slug":"double-declining-balance","name":"Double-Declining-Balance Depreciation","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","level":"Intermediate","aliases":["declining balance","accelerated depreciation","DDB"],"formula":{"latex":"Dep_{t} = \\\\frac{2}{L}\\\\times BV_{t-1}","also":[],"text":"Depreciation in year t = (2 / L) x book value at the start of the year"},"symbols":[{"symbol":"Dep_t","meaning":"Depreciation expense in year t","unit":"money"},{"symbol":"L","meaning":"Useful life","unit":"years"},{"symbol":"BV_(t-1)","meaning":"Book value at the start of year t (cost less depreciation so far)","unit":"money"}],"when_to_use":"Use it when an asset loses value faster in its early years, such as a vehicle or technology. It gives larger expenses early and smaller ones later, and never takes the book value below salvage value.","worked_example":{"problem":"A machine costs 50,000, has a salvage value of 5,000 and a useful life of 5 years. What is the depreciation in year 2 using double-declining balance?","inputs":{"cost":50000,"salvage":5000,"life":5,"year":2},"steps":[{"label":"Double-declining rate = 2 / life","working":"2 / 5","value":"40.00%"},{"label":"Book value at the start of the year = cost x (1 - rate)^(year - 1)","working":"50000 x (1-0.4)^(2-1)","value":"30,000.00"},{"label":"Depreciation = rate x book value, never below salvage value","working":"max(0, min(0.4 x 30000, 30000-5000))","value":"12,000.00"}],"answer":"Depreciation in year 2 is 12,000.00, on a starting book value of 30,000.00."},"calculator":{"available":true,"inputs":[{"id":"cost","label":"Cost of the asset","unit":"money","type":"number","default":50000,"hint":""},{"id":"salvage","label":"Salvage value","unit":"money","type":"number","default":5000,"hint":""},{"id":"life","label":"Useful life","unit":"years","type":"number","default":5,"hint":""},{"id":"year","label":"Year to calculate","unit":"year number","type":"number","default":2,"hint":"","min":1}],"checks":[{"expr":"life>0 and year>=1 and year<=life and cost>=salvage","message":"The year must be between 1 and the useful life, and the cost cannot be below the salvage value."}],"steps":[{"id":"rate","label":"Double-declining rate = 2 / life","expr":"2/life","format":"pct2"},{"id":"bv","label":"Book value at the start of the year = cost x (1 - rate)^(year - 1)","expr":"cost*(1-rate)^(year-1)","format":"money"},{"id":"dep","label":"Depreciation = rate x book value, never below salvage value","expr":"max(0, min(rate*bv, bv-salvage))","format":"money"}],"results":["dep"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"dep":12000}},"finder":{"finds":"Depreciation in a chosen year with faster early write-off","needs":"Cost, salvage value, life, year"},"related":[{"slug":"straight-line-depreciation","name":"Straight-Line Depreciation"}],"related_ids":["F073"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>D</mi><mi>e</mi><msub><mi>p</mi><mi>t</mi></msub><mo>=</mo><mfrac><mn>2</mn><mi>L</mi></mfrac><mo>\xd7</mo><mi>B</mi><msub><mi>V</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\\"application/x-tex\\">Dep_{t} = \\\\frac{2}{L}\\\\times BV_{t-1}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"dollar-cost-averaging","name":"Dollar-Cost Averaging Average Cost"},"next":{"slug":"dual-class-voting-power","name":"Dual-Class Shares: Voting Power vs. Ownership"},"lesson":null,"total":522}')}}]);